### ✅ Basic Dice Roller (Single Die)

```cpp
#include <iostream>
#include <random>
#include <chrono>

int rollDie(int sides = 6) {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, sides);
    return dis(gen);
}

int main() {
    std::cout << "Rolling a d6... " << rollDie() << std::endl;
    return 0;
}
```

