### 🚀 Enhanced Version (Multiple Dice, Different Types, Sum)

```cpp
#include <iostream>
#include <vector>
#include <random>
#include <chrono>
#include <iomanip>

class DiceRoller {
private:
    std::random_device rd;
    std::mt19937 gen;

public:
    DiceRoller() : gen(rd()) {}

    int roll(int sides = 6) {
        std::uniform_int_distribution<> dis(1, sides);
        return dis(gen);
    }

    std::vector<int> rollMultiple(int numDice, int sides = 6) {
        std::vector<int> results;
        for (int i = 0; i < numDice; ++i) {
            results.push_back(roll(sides));
        }
        return results;
    }

    int rollSum(int numDice, int sides = 6) {
        int total = 0;
        for (int i = 0; i < numDice; ++i) {
            total += roll(sides);
        }
        return total;
    }

    void displayRoll(const std::vector<int>& rolls) {
        std::cout << "[";
        for (size_t i = 0; i < rolls.size(); ++i) {
            std::cout << rolls[i];
            if (i < rolls.size() - 1) std::cout << ", ";
        }
        std::cout << "]";
    }
};

int main() {
    DiceRoller roller;

    std::cout << "=== Simple Dice Roller ===\n\n";

    // Single die
    std::cout << "1. Single d6 roll: " << roller.roll() << "\n\n";

    // Multiple dice
    auto rolls = roller.rollMultiple(3, 6);
    std::cout << "2. Roll 3d6: ";
    roller.displayRoll(rolls);
    std::cout << " = " << roller.rollSum(3, 6) << "\n\n";

    // Different dice types
    std::cout << "3. Different dice types:\n";
    std::cout << "   1d20: " << roller.roll(20) << "\n";
    std::cout << "   2d10: " << roller.rollSum(2, 10) << "\n";
    std::cout << "   4d8:  " << roller.rollSum(4, 8) << "\n";

    return 0;
}
```

